insert into public.library_versions (content_version, schema_version, language, checksum, source, model_runner_assumptions, category_legend, zone_map, load_monitoring, practical_rules, safety, individual_adaptation, glossary, bibliography) values
  ('2026.10', '1.0.0', 'es-AR', '28834da812d0dde63d38d1b6594099e738901fffb9b3aa34af1315a29d2ad0f1', '{"theoretical_base":"Planificación de resistencia aeróbica: López Chicharro vs. autores europeos (12 de octubre de 2026)","human_readable":"Biblioteca_planes_running.pdf"}'::jsonb, '{"note":"Distancias y tiempos estimados con un corredor modelo por capítulo; el usuario se guía por minutos e intensidad.","chapter1_kmh":{"walk":6,"rec":7.5,"suave":8,"mod":9},"chapter2_kmh":{"walk":6,"rec":8.5,"suave":9.5,"mod":10.5,"umb":11,"r10":11.3,"int":11.8,"vel":13,"test":11.2},"chapter3_kmh":{"walk":6,"rec":10,"suave":11.5,"mod":13,"umb":14.2,"rp":14,"r10":15,"int":15.5,"vel":17,"test":14.6},"chapter4_kmh":{"walk":6,"rec":10,"suave":11.2,"mod":13.3,"rp":13.3,"umb":14.4,"r10":15,"int":15.6,"vel":17,"test":14.6,"h21":13.9}}'::jsonb, '{"rest":"Descanso","rec":"Recuperación","easy":"Suave","mod":"Moderado","thr":"Umbral / ritmo 21-42 km / control","hard":"Intenso","race":"Competencia"}'::jsonb, '{"Recuperación":"Z1","Suave":"Z1","Moderado":"Z2","Umbral":"Z2","Intenso":"Z3","Velocidad":"Z3"}'::jsonb, '[{"signal":"Dolor (0–10)","continue":"≤2 y no empeora al correr","reduce_or_repeat":"3–5, o empeora durante la sesión: cortar la sesión y repetir la semana con menos volumen","stop_and_consult":"Más de 5, cojera, dolor localizado en un hueso, hinchazón o dolor que despierta de noche"},{"signal":"RPE de los rodajes Suaves","continue":"3–4","reduce_or_repeat":"5–6 de forma habitual para el mismo ritmo: repetir la semana","stop_and_consult":"—"},{"signal":"Calidad (series)","continue":"Repeticiones parejas con el RPE indicado","reduce_or_repeat":"No completa las repeticiones o pierde más de 5% de ritmo: cortar la serie y repetir la semana","stop_and_consult":"—"},{"signal":"Sueño","continue":"Habitual","reduce_or_repeat":"Dos o más noches malas seguidas: cambiar la calidad por un rodaje Suave","stop_and_consult":"—"},{"signal":"Fatiga al día siguiente","continue":"Desaparece en 24 h","reduce_or_repeat":"Persiste más de 48 h: un día extra de descanso y repetir la semana","stop_and_consult":"Fatiga inusual con mareos, palpitaciones, falta de aire o dolor en el pecho"},{"signal":"Enfermedad","continue":"—","reduce_or_repeat":"Resfrío leve sin fiebre: solo Suave y más corto","stop_and_consult":"Fiebre o síntomas generales: no entrenar; volver de forma gradual"}]'::jsonb, '["Sesión perdida: no se recupera al día siguiente; se sigue con la próxima sesión. Si se pierde la sesión de calidad, se hace la siguiente del plan, no ambas juntas.","Dos o más sesiones perdidas en una semana: repetir la semana.","Una semana perdida: retomar con la semana anterior a la que tocaba.","Dos semanas o más sin entrenar: retroceder al menos dos semanas, o volver a la última semana de descarga.","Mover días: se pueden cambiar los días si se respeta que entre dos sesiones exigentes haya al menos un día fácil o de descanso.","Nunca se suben a la vez el volumen, la intensidad y la frecuencia: si se agrega un día, ese día es Suave.","Si la persona no cumple el criterio de progresión dos semanas seguidas, se pasa a un plan más largo o se vuelve a la última descarga."]'::jsonb, '["Antes de empezar, consulta médica si hay enfermedad cardiovascular, metabólica o respiratoria conocida, antecedentes familiares de muerte súbita, embarazo, o síntomas al esfuerzo.","Suspender de inmediato y buscar atención si aparece dolor u opresión en el pecho, falta de aire desproporcionada, mareo, desmayo o palpitaciones irregulares.","No correr con fiebre ni con síntomas generales. Volver de forma gradual tras una enfermedad.","Dolor localizado en un hueso, dolor que empeora al correr o que obliga a cambiar la pisada: suspender y consultar a un profesional de la salud.","En calor y humedad, bajar el ritmo y acortar las sesiones de calidad. En frío, abrigo por capas.","Correr de cara al tránsito cuando no hay vereda; ropa visible y luz en horario nocturno.","Ningún plan elimina el riesgo de lesión. Los planes reducen errores de carga, pero la respuesta de cada persona es distinta.","Esta biblioteca no contiene recomendaciones médicas personalizadas."]'::jsonb, '[{"situation":"Corre más lento que el corredor modelo","adaptation":"Mantener los minutos. En sesiones por distancia (tiradas en km, series en metros), si el tiempo real supera en más de 15% el estimado, acortar la distancia para respetar el tiempo estimado."},{"situation":"Corre más rápido que el corredor modelo","adaptation":"Mantener los minutos e intensidades: hará más km. No agregar sesiones."},{"situation":"Volumen actual menor que el requisito","adaptation":"Elegir un plan más largo o hacer 3–6 semanas previas en Suave hasta alcanzar el requisito."},{"situation":"Historial de lesiones por sobrecarga","adaptation":"Elegir la frecuencia más baja posible, reemplazar uno de los rodajes por bicicleta o elíptica y priorizar la fuerza."},{"situation":"Edad avanzada o recuperación lenta","adaptation":"Más días de recuperación entre sesiones exigentes; descargas cada 3 semanas (2+1) en lugar de 3+1."},{"situation":"Calor, altitud o terreno con desnivel","adaptation":"Regular por RPE y prueba del habla, no por ritmo."},{"situation":"Calendario personal (viajes, trabajo)","adaptation":"Mover días respetando un día fácil entre dos exigentes; si se pierde la semana, ver Reglas prácticas."},{"situation":"Competencia intermedia en otra fecha","adaptation":"Mover la semana de descarga para que coincida con la competencia."},{"situation":"Objetivo de solo completar (21,1 / 42,195 km)","adaptation":"Hacer los bloques a ritmo de competencia en Moderado y ajustar el ritmo objetivo a esa sensación."}]'::jsonb, '[{"term":"Capacidad aeróbica","definition":"Capacidad de sostener esfuerzos largos con energía de origen aeróbico; se desarrolla sobre todo en fase I."},{"term":"Potencia aeróbica (VO2máx)","definition":"Máximo consumo de oxígeno; se estimula con intervalos en fase III."},{"term":"VT1 / LT1 (umbral aeróbico)","definition":"Primer umbral ventilatorio o de lactato; límite entre fase I y fase II."},{"term":"VT2 / MLSS (umbral anaeróbico)","definition":"Segundo umbral ventilatorio o máximo estado estable de lactato; límite entre fase II y fase III."},{"term":"Fases metabólicas","definition":"Modelo de López Chicharro: fase I por debajo de VT1, fase II entre VT1 y VT2, fase III por encima de VT2."},{"term":"Zona (Z1, Z2, Z3)","definition":"Agrupación de intensidades por fase metabólica."},{"term":"RPE","definition":"Percepción subjetiva del esfuerzo en escala de 1 a 10."},{"term":"Prueba del habla","definition":"Evaluación de la intensidad según cuánto se puede hablar mientras se corre."},{"term":"Distribución piramidal","definition":"Mucho Z1, menos Z2 y todavía menos Z3."},{"term":"Distribución polarizada","definition":"Mucho Z1, poco Z2 y una proporción mayor de Z3."},{"term":"Umbral fraccionado","definition":"Repeticiones en Umbral con pausas cortas, para acumular más tiempo a esa intensidad con menos fatiga."},{"term":"Mesociclo","definition":"Bloque de semanas con un objetivo común; aquí, en general, 3 semanas de carga + 1 de descarga."},{"term":"Descarga","definition":"Semana con menos volumen para asimilar la carga."},{"term":"Puesta a punto (taper)","definition":"Reducción de volumen antes de la competencia, manteniendo intensidad y frecuencia."},{"term":"Economía de carrera","definition":"Energía necesaria para correr a una velocidad dada; mejora con volumen, fuerza y técnica."},{"term":"Durabilidad","definition":"Capacidad de mantener la economía y el rendimiento tras horas de esfuerzo."},{"term":"Ritmo objetivo","definition":"Ritmo previsto para la competencia, calculado con una marca reciente o un control."},{"term":"Progresivos","definition":"Aceleraciones cortas (20\") hasta un ritmo rápido y relajado, con recuperación completa."},{"term":"Volumen","definition":"Cantidad de entrenamiento (km o minutos) en un período."},{"term":"Densidad","definition":"Relación entre el tiempo de esfuerzo y el de pausa dentro de una sesión."},{"term":"Corredor modelo","definition":"Corredor hipotético con ritmos declarados, usado para estimar distancias y tiempos."}]'::jsonb, '{"pdf":["López Chicharro, J. — Listado oficial de artículos científicos publicados. fisiologiadelejercicio.com","López Chicharro, J. y Fernández Vaquero, A. — Fisiología del ejercicio, 4.ª ed. Panamericana (2022–2023).","López Chicharro, J., Vicente-Campos, D. y Cancino, J. — Fisiología del entrenamiento aeróbico. Una visión integrada. Panamericana (2013).","López Chicharro, J. — HIIT: Entrenamiento interválico de alta intensidad (libro).","López Chicharro, J. — Entrenamiento en Zona 2 – Modelo de fases metabólicas (formación, 2026).","López Chicharro, J. — Artículos de blog: Modelo trifásico de intensidad; Tiempo dedicado al HIIT; Un verdadero HIIT; Efectos de dos modalidades de HIIT en corredores aficionados; HIIT frente a continuo para media maratón; El volumen de entrenamiento mejora la economía de carrera. fisiologiadelejercicio.com","Oliveira, P. S., Boppre, G. y Fonseca, H. (2024). Sports Medicine.","Casado, A., González-Mohíno, F., González-Ravé, J. M. y Foster, C. (2022). International Journal of Sports Physiology and Performance.","Filipas, L., Bonato, M., Gallo, G. y Codella, R. (2022). Scandinavian Journal of Medicine & Science in Sports.","Muñoz, I., Seiler, S., Bautista, J., España, J., Larumbe, E. y Esteve-Lanao, J. (2014). International Journal of Sports Physiology and Performance.","Esteve-Lanao, J. y col. (2007). Journal of Strength and Conditioning Research.","Haugen, T., Sandbakk, Ø., Seiler, S. y Tønnessen, E. (2022). Sports Medicine – Open.","Casado, A., Foster, C., Bakken, M. y Tjelta, L. I. (2023). International Journal of Environmental Research and Public Health.","Revisión de alcance sobre entrenamiento polarizado frente a otros modelos (2025). Journal of Strength and Conditioning Research.","Blagrove, R. C., Howatson, G. y Hayes, P. R. (2018). Sports Medicine.","Nielsen, R. O. y col. (2014). Journal of Orthopaedic & Sports Physical Therapy.","Bosquet, L., Montpetit, J., Arvisais, D. y Mujika, I. (2007). Medicine & Science in Sports & Exercise.","Meta-análisis de puesta a punto en deportes de resistencia (2023). PLOS ONE.","Zanini, M., Folland, J. P. y Blagrove, R. C. (2025). Medicine & Science in Sports & Exercise."],"complementary":[{"ref":"Riegel, P. S. (1981). Athletic records and human endurance. American Scientist, 69(3), 285–290.","use":"Fórmula de predicción de tiempos entre distancias."},{"ref":"Vickers, A. J. y Vertosick, E. A. (2016). An empirical study of race times in recreational endurance runners. BMC Sports Science, Medicine and Rehabilitation, 8, 26. doi:10.1186/s13102-016-0052-y","use":"Límites de la fórmula de Riegel en maratón."},{"ref":"Foster, C. y col. (2001). A new approach to monitoring exercise training. Journal of Strength and Conditioning Research, 15(1), 109–115.","use":"Uso del RPE para controlar la carga."},{"ref":"Seiler, S. (2010). What is best practice for training intensity and duration distribution in endurance athletes? International Journal of Sports Physiology and Performance, 5(3), 276–291.","use":"Distribución de intensidades."},{"ref":"Mujika, I. y Padilla, S. (2003). Scientific bases for precompetition tapering strategies. Medicine & Science in Sports & Exercise, 35(7), 1182–1187.","use":"Puesta a punto."},{"ref":"Jeukendrup, A. (2014). A step towards personalized sports nutrition: carbohydrate intake during exercise. Sports Medicine, 44(Suppl 1), S25–S33.","use":"Ensayo de la alimentación en carrera."},{"ref":"Thomas, D. T., Erdman, K. A. y Burke, L. M. (2016). Position of the Academy of Nutrition and Dietetics, Dietitians of Canada, and the American College of Sports Medicine: Nutrition and Athletic Performance.","use":"Alimentación general del deportista."},{"ref":"Casado, A., Foster, C., Bakken, M. y Tjelta, L. I. (2023). Does lactate-guided threshold interval training within a high-volume low-intensity approach represent the “next step” in the evolution of distance running training? IJERPH, 20(5), 3782. doi:10.3390/ijerph20053782","use":"Referencia completa del trabajo citado en el PDF."},{"ref":"Zanini, M., Folland, J. P. y Blagrove, R. C. (2025). Medicine & Science in Sports & Exercise. doi:10.1249/MSS.0000000000003840","use":"Referencia completa del trabajo citado en el PDF."}]}'::jsonb)
insert into public.library_intensities (content_version, position, name, zone, rpe, talk_test, feel, use_for) values
  ('2026.10', 1, 'Recuperación', 'Z1 (fase I)', '1–2', 'Conversación fluida', 'Muy fácil; podría seguir mucho tiempo', 'Caminatas, trote muy suave, pausas'),
  ('2026.10', 2, 'Suave', 'Z1 (fase I)', '3–4', 'Frases largas cómodas', 'Cómodo; respiración controlada', 'Rodajes, tiradas largas, mayor parte del volumen'),
  ('2026.10', 3, 'Moderado', 'Z2 baja (fase II)', '5', 'Frases de 5–8 palabras', 'Exigente pero sostenible mucho rato', 'Ritmo de maratón, tramos finales de tiradas, cambios en principiantes'),
  ('2026.10', 4, 'Umbral', 'Z2 alta (fase II)', '6–7', 'Frases de 2–4 palabras', 'Cómodamente duro; sostenible ≈ 1 hora en carrera', 'Umbral fraccionado y continuo, ritmo de 15–21 km'),
  ('2026.10', 5, 'Intenso', 'Z3 (fase III)', '8–9', 'Palabras sueltas', 'Duro; solo sostenible unos minutos por repetición', 'Intervalos a ritmo de 3–10 km, cuestas'),
  ('2026.10', 6, 'Velocidad', 'Z3 (fase III)', 'Rápido y relajado', 'No se habla', 'Rápido sin tensión, muy breve', 'Progresivos de 20" (técnica y economía)')
insert into public.library_session_types (content_version, position, code, name, description, purpose) values
