  ('2026.10', 10, 'INT', 'Intervalos', 'Repeticiones a ritmo de 3–10 km con pausa de trote', 'Potencia aeróbica (VO2máx)'),
  ('2026.10', 11, 'CUE', 'Cuestas', 'Subidas cortas al 4–6% con vuelta caminando o trotando', 'Fuerza específica y economía'),
  ('2026.10', 12, 'RC', 'Ritmo de competencia', 'Bloques al ritmo objetivo de 10 km, 21,1 km o maratón', 'Especificidad'),
  ('2026.10', 13, 'CTRL', 'Control', 'Test de 30'' o carrera de control', 'Evaluar y recalcular ritmos'),
  ('2026.10', 14, 'COMP', 'Competencia', 'Competencia intermedia u objetivo', 'Rendir y ensayar la estrategia'),
  ('2026.10', 15, '+F', 'Fuerza', 'Rutina A, B o C según el capítulo', 'Economía, tolerancia a la carga, prevención')
insert into public.library_strength_exercises (content_version, routine, position, exercise, target, sets_reps) values
