-- RUNNER 360 — Biblioteca de planes de running.
-- GENERADO por packages/plan-library/scripts/generate-seed.ts desde content/training-plans/running_plans_library.json.
-- No editar a mano: para cambiar el contenido, subí content_version en el JSON y regenerá.
-- runner360:reapply-on-change

-- Biblioteca de planes 2026.10 (huella 28834da812d0dde63d38d1b6594099e738901fffb9b3aa34af1315a29d2ad0f1)

do $guard$
begin
  if exists (select 1 from public.library_versions where content_version = '2026.10' and checksum <> '28834da812d0dde63d38d1b6594099e738901fffb9b3aa34af1315a29d2ad0f1') then
    raise exception 'La content_version % ya fue importada con otro contenido: subí content_version en el JSON', '2026.10';
  end if;
end
$guard$;

on conflict (content_version) do nothing;

on conflict (content_version, name) do nothing;

on conflict (content_version, code) do nothing;

on conflict (content_version, routine, position) do nothing;

on conflict (content_version, id) do nothing;

on conflict (content_version, plan_id, week) do nothing;

on conflict (content_version, plan_id, week) do nothing;

on conflict (content_version, plan_id, week, day_index) do nothing;

on conflict (content_version, plan_id, week, day_index) do nothing;

on conflict (content_version, plan_id, week, day_index) do nothing;

on conflict (content_version, plan_id, week, day_index) do nothing;

on conflict (content_version, plan_id, week, day_index) do nothing;

on conflict (content_version, plan_id, week, day_index) do nothing;

on conflict (content_version, plan_id, week, day_index) do nothing;

on conflict (content_version, plan_id, week, day_index) do nothing;

on conflict (content_version, plan_id, week, day_index) do nothing;

on conflict (content_version, plan_id, week, day_index) do nothing;

on conflict (content_version, plan_id, week, day_index) do nothing;

on conflict (content_version, plan_id, week, day_index) do nothing;

update public.library_versions set is_current = false where is_current and content_version <> '2026.10';

update public.library_versions set is_current = true where content_version = '2026.10' and not is_current;

-- Registro de lo instalado (lo usa scripts/db/migrate.mjs para aplicar solo lo nuevo).
create schema if not exists runner360_meta;
create table if not exists runner360_meta.schema_migrations (version text primary key, applied_at timestamptz not null default now());
on conflict do nothing;
